import java.io.IOException;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

public class Solution {
    static class BrokerIdempotente {
        private final List<String> log = new ArrayList<>();
        private final Map<String, Long> ultimas = new HashMap<>();
        private int falhasPendentes = 0;

        boolean publicar(String produtorId, String chave, long sequencia, String valor) {
            if (falhasPendentes > 0) {
                falhasPendentes--;
                try {
                    throw new IOException("falha simulada");
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            int particao = Math.floorMod(chave.hashCode(), 3);
            String chaveEstado = produtorId + ":" + particao;
            long ultima = ultimas.getOrDefault(chaveEstado, -1L);
            if (sequencia <= ultima) return false;
            if (sequencia > ultima + 1) {
                throw new IllegalStateException(
                    "gap de sequencia: esperado " + (ultima + 1) + ", recebido " + sequencia);
            }
            log.add(valor);
            ultimas.put(chaveEstado, sequencia);
            return true;
        }

        List<String> log() { return List.copyOf(log); }

        void falharNaProximaPublicacao() { falhasPendentes++; }
    }

    static class ProdutorIdempotente {
        private final String id;
        private final BrokerIdempotente broker;
        private final Map<String, Long> sequencias = new HashMap<>();

        ProdutorIdempotente(String id, BrokerIdempotente broker) {
            this.id = id;
            this.broker = broker;
        }

        void enviar(String chave, String valor) {
            long sequencia = proximaSequencia(chave);
            for (int tentativa = 1; tentativa <= 3; tentativa++) {
                try {
                    broker.publicar(id, chave, sequencia, valor);
                    sequencias.put(chave, sequencia + 1);
                    return;
                } catch (RuntimeException e) {
                    if (!(e.getCause() instanceof IOException)) throw e;
                }
            }
            throw new IllegalStateException("falha apos 3 tentativas");
        }

        long proximaSequencia(String chave) {
            return sequencias.getOrDefault(chave, 0L);
        }
    }
}

