import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import java.util.List;

class SolutionTest {
    @Test void envioNormalGravaUmaVez() {
        var broker = new Solution.BrokerIdempotente();
        var p = new Solution.ProdutorIdempotente("p1", broker);
        p.enviar("pedido-1", "criado");
        assertEquals(List.of("criado"), broker.log());
        assertEquals(1, p.proximaSequencia("pedido-1"));
    }

    @Test void retryAposFalhaNaoDuplica() {
        var broker = new Solution.BrokerIdempotente();
        var p = new Solution.ProdutorIdempotente("p1", broker);
        broker.falharNaProximaPublicacao();
        p.enviar("pedido-1", "criado");
        assertEquals(List.of("criado"), broker.log());
        assertEquals(1, p.proximaSequencia("pedido-1"));
    }

    @Test void brokerIgnoraDuplicata() {
        var broker = new Solution.BrokerIdempotente();
        assertTrue(broker.publicar("p1", "k", 0, "a"));
        assertFalse(broker.publicar("p1", "k", 0, "a"));
        assertEquals(List.of("a"), broker.log());
    }

    @Test void gapDeSequenciaFalha() {
        var broker = new Solution.BrokerIdempotente();
        assertThrows(IllegalStateException.class,
            () -> broker.publicar("p1", "k", 2, "a"));
        assertTrue(broker.log().isEmpty());
    }

    @Test void produtoresIndependentes() {
        var broker = new Solution.BrokerIdempotente();
        var p1 = new Solution.ProdutorIdempotente("p1", broker);
        var p2 = new Solution.ProdutorIdempotente("p2", broker);
        p1.enviar("mesma-chave", "a");
        p2.enviar("mesma-chave", "b");
        assertEquals(List.of("a", "b"), broker.log());
    }

    @Test void tresFalhasLancam() {
        var broker = new Solution.BrokerIdempotente();
        var p = new Solution.ProdutorIdempotente("p1", broker);
        broker.falharNaProximaPublicacao();
        broker.falharNaProximaPublicacao();
        broker.falharNaProximaPublicacao();
        assertThrows(IllegalStateException.class, () -> p.enviar("k", "v"));
        assertTrue(broker.log().isEmpty());
        assertEquals(0, p.proximaSequencia("k"));
    }
}
